using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEngine.SceneManagement;using UnityEditor;
[InitializeOnLoad]public static class CityTaxiStandBuild{static CityTaxiStandBuild(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode||!File.Exists("CityTaxiStand.request"))return;var mode=File.ReadAllText("CityTaxiStand.request").Trim();File.Delete("CityTaxiStand.request");try{if(mode=="build")Build();else if(mode=="refine")Refine();else Audit();}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/TaxiStand.txt",e.ToString());Debug.LogException(e);}}
static void Audit(){var s=SceneManager.GetActiveScene();var b=new StringBuilder("SCENE="+s.path+"\n");foreach(var t in s.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).Where(x=>x.name=="building_a_02_Material #163_0 (39)")){b.AppendLine("TARGET="+t.name+" pos="+t.position+" rot="+t.eulerAngles+" scale="+t.lossyScale);foreach(var r in t.GetComponentsInChildren<Renderer>(true))b.AppendLine("RENDERER="+r.name+" bounds="+r.bounds+" materials="+string.Join("|",r.sharedMaterials.Select(x=>AssetDatabase.GetAssetPath(x))));var cap=typeof(FinalPNGCityDetails).GetMethod("Capture",System.Reflection.BindingFlags.Static|System.Reflection.BindingFlags.NonPublic);var rs=t.GetComponentsInChildren<Renderer>(true);if(rs.Length>0){var box=rs[0].bounds;cap.Invoke(null,new object[]{s,box.center+new Vector3(35,25,35),box.center,"TaxiStand-Before"});}foreach(var r in s.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Renderer>(true)).Where(r=>Vector3.Distance(r.bounds.center,t.position)<45).Take(45))b.AppendLine("NEAR="+r.name+" bounds="+r.bounds);}
File.WriteAllText("FinalEnvironmentRoadReview/TaxiStand.txt",b.ToString());}static void Build(){const string dir="Assets/Scenes/Oasis/TaxiStand";var scene=SceneManager.GetActiveScene();var target=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<Transform>(true)).Single(x=>x.name=="building_a_02_Material #163_0 (39)");var renderer=target.GetComponent<Renderer>();var originalMesh=target.GetComponent<MeshFilter>().sharedMesh;var originalMatrix=target.localToWorldMatrix;var originalMaterial=renderer.sharedMaterial;var bounds=renderer.bounds;string bk="FinalEnvironmentRoadBackup/BeforeTaxiStand";Directory.CreateDirectory(bk);if(!File.Exists(bk+"/Scene.unity"))UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene,bk+"/Scene.unity",true);var existing=scene.GetRootGameObjects().FirstOrDefault(x=>x.name=="Taxi Stand - Corner 39");if(existing)throw new Exception("Taxi stand already exists; refusing duplicate placement.");var near=StackHouse3DSigns.BuildTaxiStandMeshes(true);var far=StackHouse3DSigns.BuildTaxiStandMeshes(false);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat");if(ShaderUtil.ShaderHasError(material.shader))throw new Exception("Existing shared shader has errors");var root=new GameObject("Taxi Stand - Corner 39");root.transform.position=new Vector3(bounds.center.x,27.69f,bounds.center.z);var nearRenderers=new System.Collections.Generic.List<Renderer>();var farRenderers=new System.Collections.Generic.List<Renderer>();int nearTriangles=0,farTriangles=0;for(int i=0;i<near.Length;i++){foreach(bool detailed in new[]{true,false}){var mesh=detailed?near[i]:far[i];string path=dir+"/"+mesh.name+".asset";var old=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(old){EditorUtility.CopySerialized(mesh,old);UnityEngine.Object.DestroyImmediate(mesh);mesh=old;}else AssetDatabase.CreateAsset(mesh,path);var go=new GameObject(mesh.name);go.transform.SetParent(root.transform,false);go.AddComponent<MeshFilter>().sharedMesh=mesh;var r=go.AddComponent<MeshRenderer>();r.sharedMaterial=material;r.shadowCastingMode=i==3?UnityEngine.Rendering.ShadowCastingMode.Off:UnityEngine.Rendering.ShadowCastingMode.On;r.receiveShadows=true;GameObjectUtility.SetStaticEditorFlags(go,StaticEditorFlags.OccludeeStatic);if(detailed){nearRenderers.Add(r);nearTriangles+=mesh.triangles.Length/3;}else{farRenderers.Add(r);farTriangles+=mesh.triangles.Length/3;}}}
var lod=root.AddComponent<LODGroup>();lod.SetLODs(new[]{new LOD(.13f,nearRenderers.ToArray()),new LOD(.004f,farRenderers.ToArray())});lod.RecalculateBounds();foreach(float x in new[]{-5.65f,5.65f})foreach(float z in new[]{-3.7f,6.95f}){var box=root.AddComponent<BoxCollider>();box.center=new Vector3(x,2.24f,z);box.size=new Vector3(.30f,4.48f,.30f);}var roof=root.AddComponent<BoxCollider>();roof.center=new Vector3(0,4.85f,1.8f);roof.size=new Vector3(12.8f,.70f,12.9f);var booth=root.AddComponent<BoxCollider>();booth.center=new Vector3(3.95f,1.55f,-6.5f);booth.size=new Vector3(3.75f,3.1f,3.6f);GameObjectUtility.SetStaticEditorFlags(root,StaticEditorFlags.OccludeeStatic);target.gameObject.SetActive(false);PrefabUtility.SaveAsPrefabAssetAndConnect(root,dir+"/Taxi Stand - Three Bays and Booking Booth.prefab",InteractionMode.AutomatedAction);if(target.GetComponent<MeshFilter>().sharedMesh!=originalMesh||target.localToWorldMatrix!=originalMatrix||renderer.sharedMaterial!=originalMaterial)throw new Exception("Original building was changed");var control=scene.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool wasNight=control&&control.IsNight;try{if(control)control.Apply(false);Capture(scene,root.transform.TransformPoint(new Vector3(19,10,27)),root.transform.TransformPoint(new Vector3(0,2.3f,0)),"TaxiStand-Day");if(control)control.Apply(true);Capture(scene,root.transform.TransformPoint(new Vector3(19,10,27)),root.transform.TransformPoint(new Vector3(0,2.3f,0)),"TaxiStand-Night");}finally{if(control)control.Apply(wasNight);}AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);File.WriteAllText("FinalEnvironmentRoadReview/TaxiStand.txt","SUCCESS: Reusable taxi stand prefab replaces the visibility of named corner building 39 within its original footprint. Original mesh, transform and material preserved; original object kept inactive for recovery. Three empty bays, black/yellow canopy, raised Taxi Stand lettering and taxi icon, checker fascia, booking booth service window and sign, emissive canopy and ceiling fixtures. No cars/plants/benches/cones/background props. Existing shared material and atlas reused; no new texture/material/realtime lights. Near triangles="+nearTriangles+" far triangles="+farTriangles+"; four renderers at each LOD; six simple box colliders; original lighting state restored. Shader errors=0.\nPrefab="+dir+"/Taxi Stand - Three Bays and Booking Booth.prefab");}
static void Refine(){const string dir="Assets/Scenes/Oasis/TaxiStand";var sc=SceneManager.GetActiveScene();var root=sc.GetRootGameObjects().Single(x=>x.name=="Taxi Stand - Corner 39");var a=StackHouse3DSigns.BuildTaxiStandMeshes(true);var b=StackHouse3DSigns.BuildTaxiStandMeshes(false);for(int i=0;i<a.Length;i++)foreach(var m in new[]{a[i],b[i]}){var saved=AssetDatabase.LoadAssetAtPath<Mesh>(dir+"/"+m.name+".asset");saved.Clear();saved.indexFormat=m.indexFormat;saved.vertices=m.vertices;saved.normals=m.normals;saved.uv=m.uv;var marks=new System.Collections.Generic.List<Vector4>();m.GetUVs(3,marks);saved.SetUVs(3,marks);saved.triangles=m.triangles;saved.RecalculateBounds();EditorUtility.SetDirty(saved);UnityEngine.Object.DestroyImmediate(m);}root.transform.position=new Vector3(root.transform.position.x,27.80f,root.transform.position.z);
foreach(var box in root.GetComponents<BoxCollider>())UnityEngine.Object.DestroyImmediate(box);
foreach(float x in new[]{-5.65f,5.65f})foreach(float z in new[]{-3.7f,6.95f}){var box=root.AddComponent<BoxCollider>();box.center=new Vector3(-3.2f+(-x*.75f+1.6f+3.2f)*1.15f,2.54f,z);box.size=new Vector3(.27f,5.08f,.30f);}
var roof=root.AddComponent<BoxCollider>();roof.center=new Vector3(2.32f,5.45f,1.8f);roof.size=new Vector3(11.04f,.7f,12.9f);
var booth=root.AddComponent<BoxCollider>();booth.center=new Vector3(-5.65f,1.55f,-1.3f);booth.size=new Vector3(3.19f,3.1f,3.6f);
foreach(float x in new[]{-2.81f,6.01f}){var island=root.AddComponent<BoxCollider>();island.center=new Vector3(-3.2f+(x+3.2f)*1.15f,.15f,x>0?.675f:1.75f);island.size=new Vector3(.72f,.30f,x>0?9.95f:12.1f);}
var signIsland=root.AddComponent<BoxCollider>();signIsland.center=new Vector3(7.106875f,.15f,6.95f);signIsland.size=new Vector3(1.17f,.30f,2.62f);root.GetComponent<LODGroup>().RecalculateBounds();var materials=root.GetComponentsInChildren<Renderer>(true).SelectMany(r=>r.sharedMaterials).Distinct().ToArray();if(materials.Length!=1||AssetDatabase.GetAssetPath(materials[0])!="Assets/Scenes/Oasis/FinalEnvironmentRoads/RoadDetailAtlas/City PNG Parking Cafe.mat"||root.GetComponentsInChildren<Light>(true).Length!=0||ShaderUtil.ShaderHasError(materials[0].shader))throw new Exception("Shared material/mobile-light validation failed");if(AssetDatabase.LoadAssetAtPath<GameObject>(dir+"/Taxi Stand - Three Bays and Booking Booth.prefab")){var error=AssetDatabase.MoveAsset(dir+"/Taxi Stand - Three Bays and Booking Booth.prefab",dir+"/Taxi Stand - Four Bays and Booking Booth.prefab");if(!string.IsNullOrEmpty(error))throw new Exception(error);}PrefabUtility.ApplyPrefabInstance(root,InteractionMode.AutomatedAction);var c=sc.GetRootGameObjects().SelectMany(x=>x.GetComponentsInChildren<CityDayNightController>(true)).FirstOrDefault();bool night=c&&c.IsNight;try{if(c)c.Apply(false);Capture(sc,root.transform.TransformPoint(new Vector3(10,6.2f,23)),root.transform.TransformPoint(new Vector3(0,2.5f,0)),"TaxiStand-Day");Capture(sc,root.transform.TransformPoint(new Vector3(-8,3.8f,13)),root.transform.TransformPoint(new Vector3(-1.1f,2.4f,1.8f)),"TaxiStand-Detail");if(c)c.Apply(true);Capture(sc,root.transform.TransformPoint(new Vector3(10,6.2f,23)),root.transform.TransformPoint(new Vector3(0,2.5f,0)),"TaxiStand-Night");}finally{if(c)c.Apply(night);}AssetDatabase.SaveAssets();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(sc);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(sc);File.AppendAllText("FinalEnvironmentRoadReview/TaxiStand.txt","\nFour-bay refinement: four slanted numbered bays (01-04), wider canopy fitted within the pavement, raised striped side walkways, taxi pylon on its own raised island, booth plinth/service counter/window reveals/panel joints and detailed canopy underside. Blue/navy architectural finish, silver trim and cyan edge strips. Raised canopy, wider forecourt and booth moved outward/back. Existing shared material and atlas only. Near="+root.GetComponent<LODGroup>().GetLODs()[0].renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3)+" far="+root.GetComponent<LODGroup>().GetLODs()[1].renderers.Sum(r=>r.GetComponent<MeshFilter>().sharedMesh.triangles.Length/3));}
static void Capture(Scene scene,Vector3 p,Vector3 target,string name){var go=new GameObject("Taxi stand review camera"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,scene);var c=go.AddComponent<Camera>();c.enabled=false;c.nearClipPlane=.1f;c.farClipPlane=5000;c.fieldOfView=58;c.transform.SetPositionAndRotation(p,Quaternion.LookRotation(target-p));UnityEngine.Rendering.Universal.CameraExtensions.GetUniversalAdditionalCameraData(c).renderPostProcessing=true;var rt=RenderTexture.GetTemporary(1400,1000,24);var old=RenderTexture.active;bool async=ShaderUtil.allowAsyncCompilation;try{ShaderUtil.allowAsyncCompilation=false;c.targetTexture=rt;for(int i=0;i<4;i++)c.Render();RenderTexture.active=rt;var tex=new Texture2D(1400,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1400,1000),0,0);tex.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/"+name+".png",tex.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);}finally{ShaderUtil.allowAsyncCompilation=async;RenderTexture.active=old;c.targetTexture=null;RenderTexture.ReleaseTemporary(rt);UnityEngine.Object.DestroyImmediate(go);}}
